import{_ as i,c as n,o as t,ag as a}from"./chunks/framework.DfL_BkQ-.js";const b=JSON.parse('{"title":"Finder-Sync-Erweiterung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/finder-sync.md","filePath":"de/guide/finder-sync.md","lastUpdated":1794112334000}'),r={name:"de/guide/finder-sync.md"};function l(d,e,s,o,c,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="finder-sync-erweiterung" tabindex="-1">Finder-Sync-Erweiterung <a class="header-anchor" href="#finder-sync-erweiterung" aria-label="Permalink to &quot;Finder-Sync-Erweiterung&quot;">​</a></h1><h2 id="uberblick" tabindex="-1">Überblick <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Überblick&quot;">​</a></h2><p>Die Nicasa Finder-Sync-Erweiterung fügt der macOS-Finder-Symbolleiste eine Schaltfläche hinzu, mit der du Bilddateien schnell verarbeiten kannst, ohne die Nicasa-Hauptapp zu öffnen.</p><h3 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h3><ul><li><strong>Bildoptimierer</strong>: ausgewählte Bilder komprimieren und optimieren</li><li><strong>KI-Bildeditor</strong>: ausgewählte Bilder mit KI bearbeiten (Reparieren, Verbessern, Füllen usw.)</li><li><strong>Schneller Zugriff über die Finder-Symbolleiste</strong></li><li><strong>Funktioniert mit mehreren ausgewählten Bildern</strong></li></ul><h2 id="installation-und-einrichtung" tabindex="-1">Installation und Einrichtung <a class="header-anchor" href="#installation-und-einrichtung" aria-label="Permalink to &quot;Installation und Einrichtung&quot;">​</a></h2><h3 id="installation-uber-die-nicasa-app" tabindex="-1">Installation über die Nicasa-App <a class="header-anchor" href="#installation-uber-die-nicasa-app" aria-label="Permalink to &quot;Installation über die Nicasa-App&quot;">​</a></h3><p>Die Finder-Sync-Erweiterung ist in der Nicasa-Hauptapp enthalten. Aktiviere die Erweiterung nach der Installation:</p><ol><li>Öffne <strong>Systemeinstellungen</strong> &gt; <strong>Erweiterungen</strong> &gt; <strong>Finder-Erweiterungen</strong></li><li>Schalte <strong>Nicasa Finder Sync</strong> ein</li></ol><h3 id="schaltflache-in-der-symbolleiste" tabindex="-1">Schaltfläche in der Symbolleiste <a class="header-anchor" href="#schaltflache-in-der-symbolleiste" aria-label="Permalink to &quot;Schaltfläche in der Symbolleiste&quot;">​</a></h3><p>Nach dem Aktivieren erscheint ein Nicasa-Symbol in der Finder-Symbolleiste.</p><p>Falls es nicht sichtbar ist:</p><ol><li>Rechtsklicke auf die Finder-Symbolleiste</li><li>Wähle <strong>Symbolleiste anpassen …</strong></li><li>Ziehe die Nicasa-Schaltfläche an die gewünschte Stelle</li></ol><h2 id="die-finder-symbolleisten-schaltflache-verwenden" tabindex="-1">Die Finder-Symbolleisten-Schaltfläche verwenden <a class="header-anchor" href="#die-finder-symbolleisten-schaltflache-verwenden" aria-label="Permalink to &quot;Die Finder-Symbolleisten-Schaltfläche verwenden&quot;">​</a></h2><h3 id="dateien-auswahlen" tabindex="-1">Dateien auswählen <a class="header-anchor" href="#dateien-auswahlen" aria-label="Permalink to &quot;Dateien auswählen&quot;">​</a></h3><p>Öffne den Finder und wähle ein oder mehrere Bilder aus. Unterstützte Formate:</p><ul><li><code>.jpg</code>, <code>.jpeg</code>, <code>.png</code>, <code>.gif</code>, <code>.bmp</code>, <code>.webp</code>, <code>.svg</code>, <code>.tiff</code>, <code>.ico</code></li></ul><h3 id="das-menu-verwenden" tabindex="-1">Das Menü verwenden <a class="header-anchor" href="#das-menu-verwenden" aria-label="Permalink to &quot;Das Menü verwenden&quot;">​</a></h3><p>Klicke auf die Nicasa-Schaltfläche und wähle:</p><table tabindex="0"><thead><tr><th>Option</th><th>Beschreibung</th></tr></thead><tbody><tr><td><strong>Bildoptimierer</strong></td><td>Komprimiert und optimiert die ausgewählten Bilder</td></tr><tr><td><strong>KI-Bildeditor</strong></td><td>Öffnet die ausgewählten Bilder im KI-Editor von Nicasa zum Reparieren, Verbessern oder Inpainting</td></tr></tbody></table><blockquote><p>⚠️ <strong>Hinweis</strong>: Wenn keine Datei ausgewählt ist, gibt die Schaltfläche einen Signalton aus und die Aktion wird nicht ausgeführt.</p></blockquote><h3 id="arbeitsablauf" tabindex="-1">Arbeitsablauf <a class="header-anchor" href="#arbeitsablauf" aria-label="Permalink to &quot;Arbeitsablauf&quot;">​</a></h3><ol><li>Wähle Bilder im Finder aus</li><li>Klicke auf die Nicasa-Symbolleisten-Schaltfläche → wähle die gewünschte Aktion</li><li>Die Nicasa-App öffnet sich automatisch und verarbeitet die ausgewählten Bilder</li></ol><h2 id="tipps" tabindex="-1">Tipps <a class="header-anchor" href="#tipps" aria-label="Permalink to &quot;Tipps&quot;">​</a></h2><ul><li>Für beste Ergebnisse wähle Bilder in einem Ordner, auf den du Zugriff hast</li><li>Du kannst mehrere Dateien gleichzeitig auswählen</li><li>Wenn ein Bild nicht geöffnet wird, prüfe, ob es eines der unterstützten Formate ist</li><li>Die Erweiterung harmoniert mit der macOS-Sandbox – du musst den Zugriff nur beim ersten Mal autorisieren</li></ul>',25)])])}const f=i(r,[["render",l]]);export{b as __pageData,f as default};
